-- Dedicated table for actionable MEO alerts generated by backend analytics
CREATE TABLE IF NOT EXISTS public.meo_alerts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  receptionist_id uuid NOT NULL REFERENCES public.receptionists(id) ON DELETE CASCADE,
  type text NOT NULL,
  severity text NOT NULL DEFAULT 'medium',
  title text NOT NULL,
  description text NOT NULL,
  estimated_impact numeric(12,2) NOT NULL DEFAULT 0,
  currency text NOT NULL DEFAULT 'USD',
  recommended_action text NOT NULL,
  status text NOT NULL DEFAULT 'open',
  acknowledged_at timestamptz,
  dismissed_at timestamptz,
  resolved_at timestamptz,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by text NOT NULL DEFAULT 'system',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT meo_alerts_severity_check CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  CONSTRAINT meo_alerts_status_check CHECK (status IN ('open', 'acknowledged', 'dismissed', 'resolved'))
);

CREATE INDEX IF NOT EXISTS idx_meo_alerts_receptionist_status_created
  ON public.meo_alerts (receptionist_id, status, created_at DESC);

CREATE UNIQUE INDEX IF NOT EXISTS idx_meo_alerts_open_signal
  ON public.meo_alerts (receptionist_id, type)
  WHERE status IN ('open', 'acknowledged');

DROP TRIGGER IF EXISTS handle_meo_alerts_updated_at ON public.meo_alerts;
CREATE TRIGGER handle_meo_alerts_updated_at
  BEFORE UPDATE ON public.meo_alerts
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

ALTER TABLE public.meo_alerts ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view MEO alerts for their receptionists" ON public.meo_alerts;
CREATE POLICY "Users can view MEO alerts for their receptionists"
  ON public.meo_alerts
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1
      FROM public.receptionists r
      WHERE r.id = meo_alerts.receptionist_id
      AND r.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "Users can update MEO alerts for their receptionists" ON public.meo_alerts;
CREATE POLICY "Users can update MEO alerts for their receptionists"
  ON public.meo_alerts
  FOR UPDATE
  USING (
    EXISTS (
      SELECT 1
      FROM public.receptionists r
      WHERE r.id = meo_alerts.receptionist_id
      AND r.user_id = auth.uid()
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1
      FROM public.receptionists r
      WHERE r.id = meo_alerts.receptionist_id
      AND r.user_id = auth.uid()
    )
  );

-- RPC used by periodic analytics job to upsert actionable alerts
CREATE OR REPLACE FUNCTION public.upsert_meo_alert(
  p_receptionist_id uuid,
  p_type text,
  p_severity text,
  p_title text,
  p_description text,
  p_estimated_impact numeric,
  p_currency text,
  p_recommended_action text,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.meo_alerts (
    receptionist_id,
    type,
    severity,
    title,
    description,
    estimated_impact,
    currency,
    recommended_action,
    metadata,
    status,
    created_by,
    acknowledged_at,
    dismissed_at,
    resolved_at
  )
  VALUES (
    p_receptionist_id,
    p_type,
    p_severity,
    p_title,
    p_description,
    COALESCE(p_estimated_impact, 0),
    COALESCE(NULLIF(p_currency, ''), 'USD'),
    p_recommended_action,
    COALESCE(p_metadata, '{}'::jsonb),
    'open',
    'system',
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (receptionist_id, type)
  WHERE meo_alerts.status IN ('open', 'acknowledged')
  DO UPDATE SET
    severity = EXCLUDED.severity,
    title = EXCLUDED.title,
    description = EXCLUDED.description,
    estimated_impact = EXCLUDED.estimated_impact,
    currency = EXCLUDED.currency,
    recommended_action = EXCLUDED.recommended_action,
    metadata = EXCLUDED.metadata,
    status = 'open',
    created_by = 'system',
    acknowledged_at = NULL,
    dismissed_at = NULL,
    resolved_at = NULL,
    updated_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.upsert_meo_alert(uuid, text, text, text, text, numeric, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_meo_alert(uuid, text, text, text, text, numeric, text, text, jsonb) TO service_role;
